if not (MODEL.exists() and VOICES.exists()):
    return fail("Kokoro model files missing")
ffmpeg = shutil.which("ffmpeg")
if not ffmpeg:
    return fail("ffmpeg not on PATH")
try:
    from kokoro_onnx import Kokoro
except ImportError:
    return fail("kokoro_onnx not importable")

out = subprocess.run(
    [ffmpeg, "-i", wav_path,
     "-af", "volumedetect", "-f", "null", "-"],
    capture_output=True, text=True)
# parse mean_volume from ffmpeg stderr
if mean_db is None:
    return fail("ffmpeg volumedetect: no mean_volume")
if mean_db <= THRESHOLD_DB:  # -40.0 dB
    return fail(f"audio too quiet ({mean_db} dB)")
